import{z as A,x as d,o as t,c as B,q as o,j as l,D as s,d as r,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"内存安全语言迁移","description":"","frontmatter":{"title":"内存安全语言迁移","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-safe-languages.md","filePath":"cs/memory-safe-languages.md","lastUpdated":1791063341000}'),p={name:"cs/memory-safe-languages.md"};function m(C,a,u,f,h,T){const E=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=o('<h1 id="内存安全语言迁移" tabindex="-1">内存安全语言迁移 <a class="header-anchor" href="#内存安全语言迁移" aria-label="Permalink to &quot;内存安全语言迁移&quot;">​</a></h1><div class="epigraph"><p>缓解堆叠提高利用代价；内存安全语言把越界、UAF、数据竞争从语义里删掉。迁移是 TCB 决策：新代码默认安全语言，遗留 C 用边界与沙箱围住。</p><footer>—— 据 Miller 对内存安全的论述；Rust 所有权；seL4 对 C 子集验证的对照；Anderson 对 TCB</footer></div><p>上一课<a href="/cs/pointer-authentication">PAC</a>仍假设 C 能写出任意写。缺口是<strong>换语义</strong>：Rust/Go/Java/.NET 等在各自模型里取消空间安全洞（不安全块与运行时漏洞除外）。本课讲迁移策略，不写语言教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 的对象模型允许本单元全部洞。安全语言：界检查、GC 或借用、类型。缺口是 FFI 与 <code>unsafe</code>：洞从边界再进来。策略：新组件默认安全语言，C 缩进 TCB。</p><p><span class="marginnote">术语翻译：TCB（可信计算基）就是你不得不「信它没漏洞」的那批代码——它出洞，一切外围防护作废。语言迁移的本质是缩小 TCB：把业务代码移出这份名单，名单上只留运行时和 FFI 这些绕不开的部分。</span></p><h3 id="运行时仍要补丁" tabindex="-1">运行时仍要补丁 <a class="header-anchor" href="#运行时仍要补丁" aria-label="Permalink to &quot;运行时仍要补丁&quot;">​</a></h3><p>GC 实现、JIT、标准库仍是 C/C++ 时，沙箱与更新策略不能停。</p><p><span class="marginnote">Chrome/Android 等公开的语言迁移叙述。seL4 用验证过的 C 子集，是另一条路，本课程最后一课再收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分绿场与棕场：新服务用安全语言；解析器等攻击面优先重写；FFI 最小化。对照硬件缓解：迁移期仍开。下一课序改「如何发现」：fuzz。</p><p><span class="marginnote">直觉类比：绿场像在空地上盖新楼，直接按新规范施工；棕场像改造还在住人的老楼——不能推倒重来，只能先把最危险的承重墙（解析器这类直接摸不可信输入的攻击面）换掉，其余先加上支撑（沙箱、硬件缓解）继续用。</span></p>',13)),(t(),l(i,null,{default:s(()=>[n(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20SAFE%5B%22%E5%86%85%E5%AD%98%E5%AE%89%E5%85%A8%E8%AF%AD%E8%A8%80%22%5D%0A%20%20OLD%5B%22%E9%81%97%E7%95%99%20C%22%5D%20--%3E%20BOX%5B%22%E6%B2%99%E7%AE%B1%E4%B8%8E%E7%BC%93%E8%A7%A3%22%5D%0A%20%20FFI%5B%22%E8%BE%B9%E7%95%8C%22%5D%20--%3E%20REV%5B%22%E5%AE%A1%E6%9F%A5%E4%B8%8E%E6%B5%8B%E8%AF%95%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"利用课序封口：从栈到硬件到语言。发现与工程课序从覆盖引导 fuzz 起，承认遗留 C 仍在。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为「改用 Rust/Go 就安全了」。实际上 GC、JIT、标准库内部可能仍是 C/C++，FFI 一调到 C，越界和 UAF 就从边界回来——所以运行时要继续打补丁、遗留部分要继续沙箱化，迁移不等于卸责。")],-1)),(t(),l(i,null,{default:s(()=>[n(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%AE%89%E5%85%A8%E8%AF%AD%E8%A8%80%E5%86%99%E7%9A%84%E4%B8%9A%E5%8A%A1%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20RT%5B%22%E8%AF%AD%E8%A8%80%E8%BF%90%E8%A1%8C%E6%97%B6%3A%20GC%2FJIT%22%5D%0A%20%20APP%20--%3E%20LIB%5B%22%E6%A0%87%E5%87%86%E5%BA%93%E5%86%85%E9%83%A8%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20APP%20--%3E%20FFI%5B%22FFI%20%E8%83%B6%E6%B0%B4%E4%B8%8E%E9%81%97%E7%95%99%20C%22%5D%0A%20%20RT%20--%3E%20TCB%5B%22%E4%BB%8D%E6%98%AF%20TCB%3A%20%E6%B2%99%E7%AE%B1%E4%B8%8E%E8%A1%A5%E4%B8%81%E4%B8%8D%E8%83%BD%E5%81%9C%22%5D%0A%20%20LIB%20--%3E%20TCB%0A%20%20FFI%20--%3E%20TCB%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较全部语言性能神话。下一课覆盖引导 fuzzing。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PAC/CET 是缓解；安全语言改语义。</li><li>FFI 与运行时仍是 TCB。</li><li>迁移是攻击面排序，不是一天重写内核。</li><li>下一课序：覆盖引导 fuzz。</li><li>出处：Miller 等对内存安全；Rustonomicon 的 unsafe 边界；Anderson；Klein et al. seL4（对照）。</li></ul>',4))])}const D=A(p,[["render",m]]);export{F as __pageData,D as default};
